        function validate(config) {
            const lang = detectLanguage();
            const fail = function (fr, en) { return { ok: false, message: lang === "en" ? en : fr }; };
            config = normalize(config);
            if (!config || typeof config !== "object") return fail("La configuration du module 029 est invalide.", "Module 029 configuration is invalid.");

            const ids = config.pages.map(function (page) { return page && page.id; });
            if (![DETAIL_PAGE_ID, SEARCH_PAGE_ID, EDIT_PAGE_ID, COLLECTION_PAGE_ID, ADD_PAGE_ID].every(function (id) { return ids.includes(id); })) {
                return fail("Les cinq pages Périodiques attendues ne sont pas configurées.", "The five expected Serials pages must be configured.");
            }

            if (!["asc", "desc"].includes(String(config.collectionSort && config.collectionSort.direction || "desc"))) {
                return fail("L'ordre de tri des fascicules doit être croissant ou décroissant.", "Issue sort direction must be ascending or descending.");
            }

            const lengthCfg = config.subscriptionLength || {};
            if (!["nextacquidate", "acqui_date"].includes(String(lengthCfg.issuesStartSource || "nextacquidate"))) {
                return fail("La date de départ du calcul des fascicules est invalide.", "Issue-count start date setting is invalid.");
            }
            if (!String(lengthCfg.buttonLabelFr || lengthCfg.buttonLabelEn || "").trim()) {
                return fail("Le bouton de calcul de durée doit avoir un libellé.", "The subscription-length button must have a label.");
            }
            const lengthSelectors = lengthCfg.selectors || {};
            for (const selectorKey of ["startDate", "endDate", "nextIssueDate", "frequency", "subtype", "length"]) {
                if (!String(lengthSelectors[selectorKey] || "").trim()) {
                    return fail("Un sélecteur du calculateur de durée est vide.", "A subscription-length selector is empty.");
                }
            }

            const gap = Number(config.layout && config.layout.gap);
            if (!Number.isFinite(gap) || gap < 0 || gap > 60) return fail("L'espacement doit être compris entre 0 et 60 px.", "Layout gap must be between 0 and 60 px.");

            const months = Number(config.calendar && config.calendar.months);
            if (!Number.isInteger(months) || months < 1 || months > 12) return fail("Le nombre de mois affichés doit être compris entre 1 et 12.", "Displayed months must be between 1 and 12.");
            const step = Number(config.calendar && config.calendar.navigationStep);
            if (!Number.isInteger(step) || step < 1 || step > 12) return fail("Le pas de navigation doit être compris entre 1 et 12 mois.", "Calendar navigation step must be between 1 and 12 months.");
            if (!["current", "latest"].includes(String(config.calendar && config.calendar.anchorMode || "current"))) return fail("Le mode d'ancrage du calendrier est invalide.", "Calendar anchor mode is invalid.");

            const ttl = Number(config.priceContext && config.priceContext.ttlMinutes);
            if (!Number.isFinite(ttl) || ttl < 5 || ttl > 1440) return fail("La durée du contexte prix doit être comprise entre 5 et 1440 minutes.", "Price-context retention must be between 5 and 1440 minutes.");

            const statusCodes = String(config.bulletinage && config.bulletinage.statusCodes || "").trim();
            if (config.bulletinage && config.bulletinage.rewriteStatuses !== false && !/^\d+(?:[\s,;]+\d+)*$/.test(statusCodes)) return fail("La liste des codes de statuts est invalide.", "Status code list is invalid.");

            const colorKeys = ["arrived", "expected", "late", "claimed", "missing", "other"];
            for (const key of colorKeys) {
                if (!/^#[0-9a-f]{6}$/i.test(String(config.colors && config.colors[key] || ""))) return fail("Une couleur de statut est invalide (#rrggbb attendu).", "A status color is invalid (#rrggbb expected).");
            }

            const assistant = config.receivingAssistant || {};
            if (!Array.isArray(assistant.presets)) return fail("La liste des préconfigurations est invalide.", "Preset list is invalid.");
            for (const preset of assistant.presets) {
                if (!preset || preset.enabled === false) continue;
                if (!String(preset.labelFr || preset.labelEn || "").trim()) return fail("Une préconfiguration active n'a pas de nom.", "An active preset has no name.");
                if (!Array.isArray(preset.values)) return fail("Une préconfiguration contient une liste de champs invalide.", "A preset has an invalid field list.");
                for (const value of preset.values) {
                    if (!value || value.enabled === false) continue;
                    if (!String(value.fieldLabel || "").trim()) return fail("Une valeur de préconfiguration ne cible aucun champ Koha.", "A preset value targets no Koha field.");
                    if (!["legacy", "replace", "append"].includes(String(value.mode || "legacy"))) return fail("Le mode d'écriture d'une préconfiguration est invalide.", "A preset write mode is invalid.");
                }
            }

            const protection = assistant.protection || {};
            if (!Array.isArray(protection.fields)) return fail("La liste des champs protégés est invalide.", "Protected-field list is invalid.");
            if (protection.unlockShortcutEnabled !== false && !/^[A-Za-z0-9]$/.test(String(protection.unlockKey || "U"))) return fail("La touche du raccourci doit être un caractère unique.", "Shortcut key must be one character.");

            const report = assistant.report || {};
            if (report.enabled !== false && !String(report.recipients || "").trim()) return fail("Au moins un destinataire est requis pour le signalement.", "At least one report recipient is required.");
            return { ok: true };
        }

        function newPreset(rootObject, fieldPath, items) {
            const n = (Array.isArray(items) ? items.length : 0) + 1;
            return {
                id: "preset-" + n,
                enabled: true,
                labelFr: "Préconfiguration " + n,
                labelEn: "Preset " + n,
                values: [
                    { enabled: true, fieldLabel: "q - Public", value: "", mode: "legacy" }
                ]
            };
        }

        function newPresetValue() {
            return { enabled: true, fieldLabel: "", value: "", mode: "legacy" };
        }

        function newProtectedField() {
            return { enabled: true, label: "" };
        }

