                        { key: "receivingAssistant.report.bodyTemplate", type: "textarea", label: { fr: "Corps du courriel", en: "Email body" }, description: { fr: "Variables : {SUBSCRIPTION}, {CALLNUMBER}, {USER}, {ISSUE}, {DATE}, {BARCODE}.", en: "Variables: {SUBSCRIPTION}, {CALLNUMBER}, {USER}, {ISSUE}, {DATE}, {BARCODE}." } }
