                        { key: "receivingAssistant.buttons.hoverBackground", type: "color", label: { fr: "Couleur au survol", en: "Hover color" } },
                        { key: "receivingAssistant.buttons.color", type: "color", label: { fr: "Couleur du texte", en: "Text color" } }
