    /* ============================================================
       Module 031 — Alerte avant vidage d'un champ
       Refonte de 031-alert-vide-champ-modif-lot.js — version 3.0.0.

       Périmètre :
       - batchMod.pl actif par défaut ;
       - additem.pl préparé mais désactivé par défaut ;
       - interception avant le gestionnaire natif Koha ;
       - aucun enregistrement automatique ;
       - dialogue HTML non bloquant via PMKConfig.confirmAction().
       ============================================================ */
    (function registerBatchFieldClearWarning031() {
        const moduleId = "batchmod-empty-field-warning";

        const defaults = {
            enabled: true,
            pages: [
                {
                    id: "tools.batchmod",
                    enabled: true,
                    path: "/cgi-bin/koha/tools/batchMod.pl"
                },
                {
                    id: "cataloguing.additem",
                    enabled: false,
                    path: "/cgi-bin/koha/cataloguing/additem.pl"
                }
            ],
            protection: {
                mode: "all"
            },
            fieldRules: [],
            dialog: {
                message: "ATTENTION !\n\n Si vous validez, le champ sera vide après la modification par lot et ce champ est important.\n\n Êtes-vous certain de vouloir vider ce champ ?"
            }
        };

        function newFieldRule() {
            return {
                enabled: true,
                label: "",
                match: ""
            };
        }

        function validate(config) {
            const lang = detectLanguage();
            const fail = function (fr, en) {
                return {
                    ok: false,
                    message: lang === "en" ? en : fr
                };
            };

            if (!config || typeof config !== "object") {
                return fail(
                    "La configuration du module 031 est invalide.",
                    "Module 031 configuration is invalid."
                );
            }

            const modes = ["all", "important", "custom"];
            const mode = config.protection && config.protection.mode;
            if (!modes.includes(mode)) {
                return fail(
                    "Le mode de protection du 031 n'est pas reconnu.",
                    "Module 031 protection mode is not recognized."
                );
            }

            if (!Array.isArray(config.pages)) {
                return fail(
                    "La liste des pages du 031 est invalide.",
                    "Module 031 page list is invalid."
                );
            }

            const allowedPages = {
                "tools.batchmod": "/cgi-bin/koha/tools/batchMod.pl",
                "cataloguing.additem": "/cgi-bin/koha/cataloguing/additem.pl"
            };

            for (const page of config.pages) {
                if (!page || !allowedPages[page.id] || page.path !== allowedPages[page.id]) {
                    return fail(
                        "Une page configurée pour le 031 n'est pas reconnue.",
                        "A page configured for module 031 is not recognized."
                    );
                }
            }

            if (!Array.isArray(config.fieldRules)) {
                return fail(
                    "La liste des champs protégés est invalide.",
                    "The protected field list is invalid."
                );
            }

            if (mode === "custom") {
                for (const rule of config.fieldRules) {
                    if (!rule || rule.enabled === false) continue;
                    if (!String(rule.match || "").trim()) {
                        return fail(
                            "Une règle de champ active ne contient aucun identifiant.",
                            "An active field rule has no identifier."
                        );
                    }
                }
            }

            const dialog = config.dialog || {};
            if (!String(dialog.message || "").trim()) {
                return fail(
                    "Le texte du message de confirmation est obligatoire.",
                    "The confirmation message text is required."
                );
            }

            return { ok: true };
        }

        registerModule({
            id: moduleId,
            schemaVersion: 3,
            name: {
                fr: "Alerte avant vidage d'un champ",
                en: "Field clearing warning"
            },
            description: {
                fr: "Demande une confirmation avant d'activer dans Koha la suppression d'un sous-champ exemplaire. Le module n'enregistre rien lui-même et laisse Koha appliquer l'action native après confirmation.",
                en: "Requests confirmation before enabling Koha's native item-subfield clearing action. The module saves nothing itself and lets Koha apply the native action after confirmation."
            },
            category: {
                fr: "Catalogue / exemplaires",
                en: "Catalog / items"
            },
            supportedPages: [
                "tools.batchmod",
                "cataloguing.additem"
            ],
            prerequisites: [],
            dependencies: [],
            defaults: defaults,
            validate: validate,
            schema: [
                {
                    type: "section",
                    id: "behavior",
                    label: {
                        fr: "Protection",
                        en: "Protection"
                    },
                    description: {
                        fr: "Le module intervient uniquement lorsque l'agent demande à Koha de supprimer le contenu d'un sous-champ. Annuler ne doit provoquer aucune modification du champ.",
                        en: "The module only intervenes when staff asks Koha to clear a subfield. Cancelling must leave the field completely unchanged."
                    },
                    fields: [
                        {
                            key: "protection.mode",
                            type: "select",
                            label: {
                                fr: "Champs à protéger",
                                en: "Fields to protect"
                            },
                            options: [
                                {
                                    value: "all",
                                    label: {
                                        fr: "Tous les champs pouvant être vidés",
                                        en: "All fields that can be cleared"
                                    }
                                },
                                {
                                    value: "important",
                                    label: {
                                        fr: "Uniquement les champs marqués importants par Koha",
                                        en: "Only fields marked important by Koha"
                                    }
                                },
                                {
                                    value: "custom",
                                    label: {
                                        fr: "Liste personnalisée de champs",
                                        en: "Custom field list"
                                    }
                                }
                            ]
                        }
                    ]
                },
                {
                    type: "section",
                    id: "pages",
                    label: {
                        fr: "Pages configurées",
                        en: "Configured pages"
                    },
                    description: {
                        fr: "La modification par lot est active par défaut. La fiche exemplaire individuelle reste désactivée tant qu'elle n'a pas été contrôlée dans votre Koha.",
                        en: "Batch item modification is enabled by default. The individual item editor stays disabled until it has been checked on your Koha."
                    },
                    fields: [
                        {
                            key: "pages",
                            type: "repeater",
                            reorder: false,
                            removable: false,
                            canAdd: function () { return false; },
                            itemTitle: function (item, index, lang) {
                                if (item && item.id === "cataloguing.additem") {
                                    return lang === "en"
                                        ? "Individual item editor — cataloguing/additem.pl"
                                        : "Fiche exemplaire — cataloguing/additem.pl";
                                }
                                return lang === "en"
                                    ? "Batch item modification — tools/batchMod.pl"
                                    : "Modification d'exemplaires par lot — tools/batchMod.pl";
                            },
                            fields: [
                                {
                                    key: "enabled",
                                    type: "boolean",
                                    label: {
                                        fr: "Activer la protection sur cette page",
                                        en: "Enable protection on this page"
                                    }
                                },
                                {
                                    key: "id",
                                    type: "readonly",
                                    advanced: true,
                                    label: {
                                        fr: "Identifiant fonctionnel",
                                        en: "Functional identifier"
                                    }
                                },
                                {
                                    key: "path",
                                    type: "readonly",
                                    label: {
                                        fr: "Chemin Koha",
                                        en: "Koha path"
                                    }
                                }
                            ]
                        }
                    ]
                },
                {
                    type: "section",
                    id: "fields",
                    when: function (root) {
                        return root && root.protection && root.protection.mode === "custom";
                    },
                    label: {
                        fr: "Champs protégés",
                        en: "Protected fields"
                    },
                    description: {
                        fr: "Ajoutez les champs à protéger lorsque le mode « Liste personnalisée » est choisi. Vous pouvez utiliser un kohafield (ex. items.homebranch), une référence MARC (ex. 952$a) ou un libellé visible.",
                        en: "Add fields to protect when “Custom field list” is selected. You can use a kohafield (for example items.homebranch), a MARC reference (for example 952$a), or a visible label."
                    },
                    fields: [
                        {
                            key: "fieldRules",
                            type: "repeater",
                            label: {
                                fr: "Règles de protection",
                                en: "Protection rules"
                            },
                            addLabel: {
                                fr: "Ajouter un champ protégé",
                                en: "Add protected field"
                            },
                            reorder: true,
                            newItem: newFieldRule,
                            itemTitle: function (item, index) {
                                return String(item && (item.label || item.match) || "").trim() ||
                                    "Champ " + (index + 1);
                            },
                            fields: [
                                {
                                    key: "enabled",
                                    type: "boolean",
                                    label: {
                                        fr: "Protection active",
                                        en: "Protection enabled"
                                    }
                                },
                                {
                                    key: "label",
                                    type: "text",
                                    label: {
                                        fr: "Nom dans la configuration",
                                        en: "Configuration name"
                                    }
                                },
                                {
                                    key: "match",
                                    type: "text",
                                    label: {
                                        fr: "Champ Koha / MARC / libellé",
                                        en: "Koha field / MARC / label"
                                    },
                                    placeholder: {
                                        fr: "Ex. items.homebranch ou 952$a",
                                        en: "E.g. items.homebranch or 952$a"
                                    }
                                }
                            ]
                        }
                    ]
                },
                {
                    type: "section",
                    id: "dialog",
                    label: {
                        fr: "Message de confirmation",
                        en: "Confirmation message"
                    },
                    description: {
                        fr: "Un seul texte est affiché. Par défaut, il reprend exactement le message du script 031 historique.",
                        en: "A single text is displayed. By default it exactly preserves the historical 031 message."
                    },
                    fields: [
                        {
                            key: "dialog.message",
                            type: "textarea",
                            rows: 5,
                            label: {
                                fr: "Texte du message",
                                en: "Message text"
                            }
                        }
                    ]
                },
                {
                    type: "section",
                    id: "safety",
                    label: {
                        fr: "Sécurité",
                        en: "Safety"
                    },
                    description: {
                        fr: "PMK ne vide aucun champ et ne soumet jamais le formulaire. Après confirmation, le clic est rejoué une seule fois afin que le gestionnaire natif de Koha applique son comportement habituel. Après annulation, l'état initial du champ est restauré.",
                        en: "PMK never clears a field and never submits the form. After confirmation, the click is replayed once so Koha's native handler applies its normal behavior. After cancellation, the original field state is restored."
                    },
                    fields: []
                }
            ],
            focusContext: function (main, context) {
                if (!main) return;
                const wanted = context && context.sectionId ? context.sectionId : "fields";
                const section =
                    main.querySelector('[data-pmk-section-id="' + wanted + '"]') ||
                    main.querySelector('[data-pmk-section-id="behavior"]');

                if (!section) return;
                window.setTimeout(function () {
                    section.scrollIntoView({
                        block: "start",
                        behavior: "smooth"
                    });
                }, 0);
            }
        });
    })();


