        function clone(value) {
            return JSON.parse(JSON.stringify(value));
        }

        function object(value) {
            return value && typeof value === "object" && !Array.isArray(value) ? value : {};
        }

        function merge(base, extra) {
            const out = clone(base);
            if (!extra || typeof extra !== "object") return out;
            Object.keys(extra).forEach(function (key) {
                if (Array.isArray(extra[key])) out[key] = clone(extra[key]);
                else if (extra[key] && typeof extra[key] === "object" && !Array.isArray(extra[key]) && out[key] && typeof out[key] === "object" && !Array.isArray(out[key])) {
                    out[key] = merge(out[key], extra[key]);
                } else if (extra[key] !== undefined) {
                    out[key] = extra[key];
                }
            });
            return out;
        }

        function num(value, min, max, fallback) {
            const n = Number(value);
            if (!Number.isFinite(n)) return fallback;
            return Math.min(max, Math.max(min, n));
        }

        function integer(value, min, max, fallback) {
            return Math.round(num(value, min, max, fallback));
        }

        function listString(value, fallback) {
            if (Array.isArray(value)) return value.map(String).join("\n");
            if (value == null) return fallback;
            return String(value);
        }

